<script lang="ts">
  import { onMount } from 'svelte';
  type Dataset={id:string;name:string;end:string;synthetic:boolean};
  type Run={id:string;datasetName:string;status:string;config:{hypothesis:string}};
  type Signal={id:string;runId:string;decisionDate:string;featureCutoff:string;generatedAt:string;inputObservedAt:string;synthetic:boolean;modelSha256:string;datasetSha256:string;predictions:{symbol:string;score:number;targetWeight:number}[]};
  type Intent={id:string;phase:string;brokerOrderId:number|null;reportedFilled:number;errorCode:string|null;intent:{symbol:string;quantity:number;limitPrice:number;quoteCurrency:string};progress:{filled:number;debitGbp:number;remainingReserve:number}};
  type Account={key:string;environment:string;account:string;allocatedCapitalGbp:number;cashGbp:number;reservedGbp:number;blockCode:string|null;intents:Intent[]};
  type Runtime={configured:boolean;enabled:boolean;automatic:boolean;environment:string;monthlyAllowanceGbp:number|null;credentialsConfigured:boolean;paused:boolean;configurationError:string|null;accounts:Account[];demoReceipts:{id:string;synthetic:boolean}[]};
  let datasets=$state<Dataset[]>([]),runs=$state<Run[]>([]),signals=$state<Signal[]>([]),runtime=$state<Runtime|null>(null),runId=$state(''),datasetId=$state(''),busy=$state(false),error=$state(''),signalError=$state(''),lastCycle=$state(''),captureNote=$state(''),bindings=$state<Record<string,string>>({});
  const money=(n:number)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n);
  const messages:Record<string,string>={'signal-current-panel-required':'A current signal needs observations through the previous calendar month. Historical engineering fixtures cannot be used as current market inputs.','execution-backtest-policy-mismatch':'The initial coordinator only buys with contributions. Select a contribution-only backtest; a full-rebalance report cannot approve this policy.','execution-private-configuration-required':'Execution is disconnected. Configure the private account, strategy and evidence files first.','execution-genuine-demo-required':'Live execution needs a genuine reconciled demo receipt for this strategy, code and rules. Synthetic rehearsals cannot provide it.'};
  async function api(path:string,body?:unknown){const response=await fetch(path,body===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json','X-Twenty-Request':'1'},body:JSON.stringify(body)});if(!response.ok){const value=await response.json();throw new Error(messages[value.error]??value.error??'service-unavailable');}return response.status===202?null:response.json();}
  async function refresh(){const [state,records]=await Promise.all([api('/api/execution/broker'),api('/api/execution/signals')]);runtime=state;signals=records;}
  async function createSignal(){busy=true;signalError='';try{await api('/api/execution/signals',{runId,datasetId});await refresh();}catch(e){signalError=e instanceof Error?e.message:'signal-failed';}finally{busy=false;}}
  async function cycle(){busy=true;error='';try{const result=await api('/api/execution/broker/cycle',{});lastCycle=`${result.status} · ${result.submitted} submissions${result.code?` · ${messages[result.code]??result.code}`:''}`;await refresh();}catch(e){error=e instanceof Error?e.message:'cycle-failed';}finally{busy=false;}}
  async function capture(){busy=true;error='';try{const result=await api('/api/execution/broker/capture',{});captureNote=`${result.environment} · ${result.positions} positions · ${result.pendingOrders} pending orders · ${result.historyRows} history rows. Exact responses were archived privately. Wallet signs/taxes still need independent review.`;}catch(e){error=e instanceof Error?e.message:'capture-failed';}finally{busy=false;}}
  async function action(path:string){busy=true;error='';try{await api(path,{});await refresh();}catch(e){error=e instanceof Error?e.message:'operation-failed';}finally{busy=false;}}
  onMount(()=>{void Promise.all([api('/api/research/datasets'),api('/api/research/runs'),refresh()]).then(([data,all])=>{datasets=data;runs=all.filter((r:Run)=>r.status==='succeeded');runId=runs[0]?.id??'';datasetId=[...datasets].sort((a,b)=>b.end.localeCompare(a.end))[0]?.id??'';}).catch(e=>error=e.message);});
</script>
<section class="panel lab-results" aria-labelledby="forward-signals-title"><div class="panel-heading"><div><p class="eyebrow">FROZEN MODEL → CURRENT INPUTS</p><h2 id="forward-signals-title">Record the choice before its outcome.</h2></div><span class="badge">UTC MONTHLY SIGNALS</span></div><p>Score a separately imported recent panel with a completed experiment's frozen model and allocation rules. This does not retrain on reserved outcomes. A local registration timestamp records when Twenty first confirmed the input; it does not certify upstream publication or data quality.</p>
<form class="signal-form" onsubmit={(e)=>{e.preventDefault();void createSignal();}}><label>Frozen experiment<select bind:value={runId} required>{#each runs as run}<option value={run.id}>{run.config.hypothesis} · {run.id.slice(0,8)}</option>{/each}</select></label><label>Latest monthly observations<select bind:value={datasetId} required>{#each datasets as dataset}<option value={dataset.id}>{dataset.name} · through {dataset.end}</option>{/each}</select></label><button disabled={busy||!runId||!datasetId}>Record current signal</button></form>
{#if signalError}<p class="error" role="alert">{signalError}</p>{/if}
{#if signals.length}<div class="table-scroll"><table><thead><tr><th>Decision month</th><th>Feature cutoff</th><th>Recorded choices</th><th>Provenance</th></tr></thead><tbody>{#each signals as signal}<tr><td>{signal.decisionDate.slice(0,7)}</td><td>{signal.featureCutoff}</td><td>{signal.predictions.filter(p=>p.targetWeight>0).map(p=>`${p.symbol} ${(p.targetWeight*100).toFixed(1)}%`).join(' · ')||'Retain cash'}</td><td>{signal.synthetic?'Synthetic inputs':'Imported inputs; audit required'}<small>Model {signal.modelSha256.slice(0,10)}… · data {signal.datasetSha256.slice(0,10)}…</small></td></tr>{/each}</tbody></table></div>{:else}<p class="dataset-note">No forward signals recorded. The bundled historical fixtures cannot become live recommendations. Import an appropriate latest-month panel to exercise this path.</p>{/if}</section>
<section class="panel lab-results" aria-labelledby="broker-ledger-title"><div class="panel-heading"><div><p class="eyebrow">ACCOUNT-BOUND EXECUTION</p><h2 id="broker-ledger-title">The broker journal.</h2></div><span class="badge" class:live-mode={runtime?.environment==='live'}>{runtime?.environment.toUpperCase()??'LOADING'}</span></div><p>One monthly allocation to the strategy sleeve; no automatic deposit and no access to the rest of the ISA as strategy capital. Share limits reserve cash, count existing holdings, and stop on uncertain submissions. Verified wallet evidence records actual GBP debits; it does not certify legal settlement.</p>
<div class="lab-metrics"><div><span>Private execution configuration</span><strong>{runtime?.enabled?'Enabled':'Disabled'}</strong></div><div><span>Automatic worker</span><strong>{runtime?.automatic?'Configured':'Off'}</strong></div><div><span>Monthly sleeve allowance</span><strong>{runtime?.monthlyAllowanceGbp?money(runtime.monthlyAllowanceGbp):'Not set'}</strong></div><div><span>Reconciled demo receipts</span><strong>{runtime?.demoReceipts.filter(r=>!r.synthetic).length??0}</strong></div></div>
<div class="execution-actions"><button disabled={busy||!runtime?.enabled||!runtime?.credentialsConfigured} onclick={()=>void cycle()}>{runtime?.environment==='live'?'Run live execution cycle':'Run demo execution cycle'}</button><button class="secondary" disabled={busy} onclick={()=>void action(`/api/execution/pause?paused=${!runtime?.paused}`)}>{runtime?.paused?'Resume new submissions':'Pause new submissions'}</button><button class="secondary" disabled={busy} onclick={()=>void refresh()}>Refresh journal</button><button class="secondary" disabled={busy||!runtime?.credentialsConfigured} onclick={()=>void capture()}>Capture read-only broker evidence</button></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}
{#if !runtime?.configured}<p class="dataset-note">Disconnected by default. Private credentials, independently inspected account identity, a current dataset, executable quotes/rules, a wallet sample profile and strategy evidence are required. Credentials never belong in this form.</p>{/if}
{#if captureNote}<p class="dataset-note">{captureNote}</p>{/if}
{#if runtime?.configurationError}<p class="error">Private configuration: {runtime.configurationError}</p>{/if}{#if lastCycle}<p class="dataset-note" aria-live="polite">{lastCycle}</p>{/if}
{#each runtime?.accounts??[] as account}<div class="broker-account"><h3>{account.environment} · account {account.account}</h3>{#if account.blockCode}<p class="error">New execution blocked: {messages[account.blockCode]??account.blockCode}. Existing reservations stay recorded.</p>{/if}<p>Allocated capital {money(account.allocatedCapitalGbp)} · sleeve cash {money(account.cashGbp)} · reserved {money(account.reservedGbp)}</p><div class="table-scroll"><table><thead><tr><th>Stock / shares</th><th>State</th><th>Observed / booked shares</th><th>Booked debit</th><th>Reserve</th><th>Reconcile</th></tr></thead><tbody>{#each account.intents as order}<tr><td>{order.intent.symbol}<small>{order.intent.quantity.toFixed(6)} shares · limit {order.intent.limitPrice} {order.intent.quoteCurrency}</small></td><td>{order.phase}{#if order.errorCode}<small>{order.errorCode}</small>{/if}</td><td>{order.reportedFilled.toFixed(6)} / {order.progress.filled.toFixed(6)}</td><td>{money(order.progress.debitGbp)}</td><td>{money(order.progress.remainingReserve)}</td><td>{#if ['planned','pending'].includes(order.phase)}<button class="secondary small-button" disabled={busy||!runtime?.enabled} onclick={()=>void action(`/api/execution/broker/${account.key}/${order.id}/cancel`)}>Request cancellation</button>{:else if order.phase==='unknown'}<label>Independently inspected broker order ID<input type="text" inputmode="numeric" bind:value={bindings[order.id]} /></label><button class="secondary small-button" disabled={busy||!bindings[order.id]||!/^\d+$/.test(bindings[order.id])} onclick={()=>void action(`/api/execution/broker/${account.key}/${order.id}/bind?orderId=${encodeURIComponent(bindings[order.id])}`)}>Bind inspected order</button>{/if}</td></tr>{/each}</tbody></table></div></div>{/each}
<a class="text-link" href="https://github.com/Jellman86/twenty/blob/dev/docs/trading212-setup.md" target="_blank" rel="noreferrer">Private setup, evidence and operating instructions ↗</a>
</section>
